 function restore(p,redo=false){const stack=redo?p.redo:p.undo;if(!stack.length)return false;const before=JSON.stringify({activities:p.activities,letters:p.letters}),saved=normalize(JSON.parse(stack.pop()));p.activities=saved.activities;p.letters=saved.letters;(redo?p.undo:p.redo).push(before);return true;}
