 function letterDraft(m,at=0){if(!m.from.trim()||!m.to.trim()||!m.subject.trim()||!m.body.trim()||!m.owner.startsWith('pc-'))throw Error('Add sender, recipient, subject, message and the receiving character.');if(/\[[^\]]+\]/.test(m.body))throw Error('Replace the player-edit placeholders before reviewing this letter.');if(!m.notes.trim())throw Error('Describe the actual message status: a player copy, dispatch, or receipt.');const body=`From ${m.from}\nTo ${m.to}\n\n${m.body}`;return {kind:'other',title:'Correspondence · '+m.subject,publicTitle:m.subject,detail:m.notes+'\n\n'+body,playerText:body,status:'confirmed',basis:'Observed',source:'DM-reviewed in-app correspondence; message status recorded explicitly',share:'private',knows:[m.owner],recipients:[m.owner],downtime:{activityId:'',jobId:'',letterId:m.id,town:m.town,minutes:0,cost:'No payment recorded by this delivery',result:'completed',at}};}
 function returnSummary(d,ledger,town){const M=globalThis.ECHO_SETTLEMENTS,s=M.summary(ledger,town),t=ledger.towns.find(t=>t.id===town);const actual=results(d).filter(e=>e.downtime.town===town&&e.downtime.at>=t.since&&!list(t.sinceOutcomeIds).includes(e.id)&&(!t.sinceOutcomeAt||e.approvedAt>=t.sinceOutcomeAt));const legacy=s.changes.filter(h=>/^(Approved |Declined |.* stock [+-]|.*confirmed \d)/.test(h.text));return {...s,actual,changes:[...legacy,...actual.map(e=>({id:e.id,town,at:e.downtime.at,text:`${e.title}: ${e.detail}`,public:e.share==='party'&&e.knows.includes('party')&&!!e.playerText}))],publicChanges:[...legacy.filter(h=>h.public).map(h=>h.text),...actual.filter(e=>e.share==='party'&&e.knows.includes('party')&&e.playerText).map(e=>e.publicTitle+': '+e.playerText)],prepared:s.changes.length-legacy.length};}
